// Normalize all jobs from all sources into a standard schema
const KEYWORDS = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data analyst','remote data scientist',
  'remote ai marketing','remote marketing analyst','remote growth analyst',
  'remote bi analyst','remote automation specialist','remote ai workflow',
  'data analyst','data scientist','business intelligence','bi analyst',
  'marketing analyst','performance marketing','growth analyst',
  'ai marketing','ai automation','ai workflow','creative strategist',
  'martech analyst'
];

const normalized = [];
const today = new Date().toISOString().split('T')[0];

for (const item of $input.all()) {
  const raw = item.json;
  let jobs = [];

  // Remote OK (returns array, first element is metadata)
  if (Array.isArray(raw) && raw[0] && raw[0].legal) {
    jobs = raw.slice(1).map(j => ({
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || `https://remoteok.com/remote-jobs/${j.id}`,
      source: 'Remote OK',
      location_text: (j.location || '') + ' ' + (j.tags || []).join(' '),
      salary: j.salary_min ? `$${j.salary_min}-$${j.salary_max}/yr` : '',
      description: (j.description || '') + ' ' + (j.tags || []).join(' '),
      posted_date: j.date || today,
      tags: (j.tags || []).join(', '),
      job_id: `remoteok_${j.id}`
    }));
  }

  // Remotive (returns {jobs: [...]})
  else if (raw.jobs && Array.isArray(raw.jobs)) {
    jobs = raw.jobs.map(j => ({
      job_title: j.title || '',
      company: j.company_name || '',
      job_url: j.url || '',
      source: 'Remotive',
      location_text: j.candidate_required_location || 'Worldwide',
      salary: j.salary || '',
      description: (j.description || '') + ' ' + j.candidate_required_location,
      posted_date: j.publication_date ? j.publication_date.split('T')[0] : today,
      tags: (j.tags || []).join(', '),
      job_id: `remotive_${j.id}`
    }));
  }

  // RSS feeds (We Work Remotely, Himalayas, Dynamite Jobs)
  else if (raw.title && raw.link && (raw.pubDate || raw['dc:date'])) {
    const sourceName = raw['source_name'] || 'RSS';
    jobs = [{
      job_title: raw.title || '',
      company: raw.author || raw['dc:creator'] || '',
      job_url: raw.link || '',
      source: sourceName,
      location_text: raw['location'] || raw.category || 'Worldwide',
      salary: '',
      description: raw.contentSnippet || raw.content || raw.summary || raw.title,
      posted_date: raw.pubDate ? new Date(raw.pubDate).toISOString().split('T')[0] : today,
      tags: raw.categories ? raw.categories.join(', ') : '',
      job_id: `rss_${Buffer.from(raw.link || raw.title).toString('base64').slice(0, 20)}`
    }];
  }

  // Text/HTML responses (YC, Wellfound, Otta) - basic extraction
  else if (typeof raw.data === 'string' || typeof raw.body === 'string') {
    // These sources require scraping - flag for future enhancement
    // For now, skip - user should add dedicated scraper nodes for these
    continue;
  }

  // Filter by keywords before adding
  for (const job of jobs) {
    const text = (job.job_title + ' ' + job.description + ' ' + job.tags).toLowerCase();
    const hasKeyword = KEYWORDS.some(kw => text.includes(kw));
    if (hasKeyword || text.includes('remote')) {
      job.date_found = today;
      normalized.push({ json: job });
    }
  }
}

return normalized;

// Deduplicate: remove jobs already in Google Sheets
const existingRows = $('Sheets: Get Existing URLs').all();
const existingUrls = new Set(existingRows.map(r => r.json.job_url).filter(Boolean));
const existingKeys = new Set(
  existingRows.map(r => `${(r.json.company||'').toLowerCase()}|${(r.json.job_title||'').toLowerCase()}`).filter(Boolean)
);

const newJobs = [];
const seen = new Set();

for (const item of $('Code: Normalize Jobs').all()) {
  const job = item.json;
  const url = job.job_url;
  const key = `${(job.company||'').toLowerCase()}|${(job.job_title||'').toLowerCase()}`;

  if (existingUrls.has(url)) continue;
  if (existingKeys.has(key)) continue;
  if (seen.has(url)) continue;

  seen.add(url);
  newJobs.push({ json: job });
}

return newJobs;

// Hard filter: reject jobs that are clearly Taiwan-ineligible
const REJECT_PATTERNS = [
  /\bus only\b/i, /\busa only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\buk only\b/i, /\bunited kingdom only\b/i,
  /\beu only\b/i, /\beurope only\b/i, /\baustralia only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i, /\bmust reside in\b/i,
  /\bauthorized to work in\b/i, /\bwork authorization\b.*\b(us|uk|eu|canada|australia)\b/i,
  /\blocal work permit\b/i, /\bwork permit required\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\boffice required\b/i,
  /\bin-office\b/i, /\bin office\b/i,
  /\bremote within (the )?(us|uk|eu|europe|canada|australia)\b/i,
  /\b(us|uk|eu|canada|australia) remote only\b/i,
  /\bfixed us hours\b/i, /\bfixed eu hours\b/i,
  /\brequires.*relocation\b/i, /\bwillingness to relocate\b/i,
  /applicants must be.*residents/i
];

const KEEP_PATTERNS = [
  /worldwide remote/i, /global remote/i, /work from anywhere/i,
  /anywhere in the world/i, /apac remote/i, /international contractors/i,
  /contractor role/i, /b2b contractor/i, /hires via deel/i,
  /hires via remote\.com/i, /hires via oyster/i, /eor supported/i,
  /employer of record/i, /remote.?first/i, /distributed team/i,
  /open to all time zones/i, /async.?first/i, /no timezone requirement/i,
  /all timezones/i, /any timezone/i
];

const passed = [];
const rejected = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title} ${job.description} ${job.location_text} ${job.tags}`.toLowerCase();

  const hasKeep = KEEP_PATTERNS.some(p => p.test(text));
  const hasReject = REJECT_PATTERNS.some(p => p.test(text));

  if (hasReject && !hasKeep) {
    job._hard_filter_result = 'rejected';
    job._hard_filter_reason = 'Matched exclusion pattern';
    rejected.push({ json: job });
  } else {
    job._hard_filter_result = 'passed';
    job._has_keep_signal = hasKeep;
    passed.push({ json: job });
  }
}

// Store rejected count in first item metadata for later digest
if (passed.length > 0) {
  passed[0].json._rejected_count = rejected.length;
}

return passed;

