// Parse AI response and merge with job data
const items = $input.all();
const results = [];

for (const item of items) {
  const job = item.json;
  let aiResult = {};

  try {
    const content = job.message?.content || job.choices?.[0]?.message?.content || '{}';
    aiResult = JSON.parse(content);
  } catch (e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'AI parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  // Reject clearly ineligible jobs
  if (aiResult.decision === 'reject' || aiResult.taiwan_eligible === 'no') {
    continue;
  }

  results.push({
    json: {
      ...job,
      taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      taiwan_reason: aiResult.reason || '',
      location_risk: aiResult.location_risk || 'medium',
      timezone_risk: aiResult.timezone_risk || 'medium',
      contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  });
}

return results;

// Async filter and role fit scoring
const ASYNC_HIGH = [
  /\basync(?:hronous)?[- ]first\b/i, /\bfully async\b/i,
  /\bno required meetings\b/i, /\blow meeting culture\b/i,
  /\bwork across time zones\b/i, /\bopen to all time zones\b/i,
  /\bno timezone requirement\b/i, /\ball timezones/i
];
const ASYNC_MED = [
  /\basync/i, /\basynchronous/i, /\bflexible hours\b/i,
  /\bflexible schedule\b/i, /\bdistributed team\b/i,
  /\bremote.?first\b/i, /\bwork from anywhere\b/i
];
const ASYNC_REJECT = [
  /\bstrict 9.?to.?5\b/i, /\bfixed (us|est|pst|cet|gmt)\b.*hours/i,
  /\bdaily live calls required\b/i, /\bmust overlap full business day\b/i,
  /\brequired to be online.*9.*5\b/i
];

const ROLE_HIGH = [
  /data analyst/i, /data scientist/i, /business intelligence/i,
  /\bbi analyst\b/i, /marketing analyst/i, /performance marketing/i,
  /growth analyst/i, /ai marketing/i, /ai automation/i,
  /ai workflow/i, /martech/i, /marketing data/i, /analytics engineer/i
];
const ROLE_MED = [
  /analyst/i, /data/i, /marketing/i, /automation/i,
  /reporting/i, /dashboard/i, /insights/i, /digital marketing/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title} ${job.description} ${job.tags}`.toLowerCase();

  // Reject hard async blockers
  if (ASYNC_REJECT.some(p => p.test(text))) continue;

  // Async level
  let async_level = 'low';
  let async_score = 0;
  if (ASYNC_HIGH.some(p => p.test(text))) {
    async_level = 'high';
    async_score = 25;
  } else if (ASYNC_MED.some(p => p.test(text))) {
    async_level = 'medium';
    async_score = 20;
  } else {
    async_score = 10; // remote at least
  }

  // Role fit
  let role_category = 'other';
  let role_score = 0;
  if (ROLE_HIGH.some(p => p.test(text))) {
    role_category = 'primary';
    role_score = 25;
  } else if (ROLE_MED.some(p => p.test(text))) {
    role_category = 'adjacent';
    role_score = 15;
  }

  // Taiwan eligibility score
  let tw_score = 0;
  if (job.taiwan_eligible === 'yes' || job._has_keep_signal) {
    const highSignals = /worldwide|work from anywhere|global remote|apac|contractor|deel|oyster|remote\.com|eor/i;
    tw_score = highSignals.test(text) ? 40 : 30;
  } else if (job.taiwan_eligible === 'unclear') {
    tw_score = 20;
  }

  // Salary score
  let salary_score = 0;
  const salaryText = job.salary || '';
  const salaryNums = salaryText.match(/\d[\d,]+/g);
  if (salaryNums && salaryNums.length > 0) {
    const num = parseInt(salaryNums[0].replace(/,/g, ''));
    if (num >= 5000 || num >= 60000) salary_score = 25;
    else if (num >= 3000 || num >= 36000) salary_score = 15;
    else salary_score = 10;
  } else if (salaryText.length > 0) {
    salary_score = 10;
  }

  const total_score = tw_score + async_score + role_score + salary_score;

  // Generate why_good_fit
  const reasons = [];
  if (tw_score >= 40) reasons.push('Clearly worldwide/contractor friendly');
  else if (tw_score >= 30) reasons.push('APAC or international friendly');
  if (async_level === 'high') reasons.push('Fully async culture');
  else if (async_level === 'medium') reasons.push('Flexible hours');
  if (role_category === 'primary') reasons.push('Strong role match (data/AI/marketing analytics)');
  if (salary_score >= 25) reasons.push('Competitive salary listed');

  results.push({
    json: {
      ...job,
      async_level,
      role_category,
      score: total_score,
      tw_score,
      async_score,
      role_score,
      salary_score,
      why_good_fit: reasons.join('; ') || 'Possible fit — needs manual check'
    }
  });
}

// Sort by score desc
results.sort((a, b) => b.json.score - a.json.score);
return results;

