// Build daily digest message
const allJobs = $input.first().json.data || [];

const topJobs = allJobs
  .filter(j => j.score >= 70)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10);

const manualCheck = allJobs
  .filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70)
  .slice(0, 5);

// Build job entries
let jobLines = '';
topJobs.forEach((job, i) => {
  jobLines += `
${i + 1}. ${job.job_title}
   Company: ${job.company}
   Score: ${job.score}/100
   Taiwan eligible: ${job.taiwan_eligible} — ${job.taiwan_reason || ''}
   Async level: ${job.async_level}
   Timezone risk: ${job.timezone_risk}
   Salary: ${job.salary || 'Not listed'}
   Why it fits Jerry: ${job.why_good_fit}
   Apply: ${job.job_url}
`;
});

let manualLines = '';
if (manualCheck.length > 0) {
  manualLines = '\n--- MANUAL CHECK NEEDED ---\n';
  manualCheck.forEach((job, i) => {
    manualLines += `${i + 1}. ${job.job_title} @ ${job.company} (Score: ${job.score}) — ${job.taiwan_reason}\n   ${job.job_url}\n`;
  });
}

const today = new Date().toISOString().split('T')[0];

const digest = `Daily Taiwan Eligible Async Remote Jobs — ${today}

Top jobs today (${topJobs.length} passed filters):
${jobLines || 'No new qualifying jobs found today.'}
${manualLines}
--- REJECTED SUMMARY ---
Jobs reviewed: ${allJobs.length}
Passed (score ≥ 70): ${topJobs.length}
Rejected by hard filter: (see Rejected sheet)
Manual check: ${manualCheck.length}
`;

return [{ json: { digest, job_count: topJobs.length, today } }];
